#nullable enable
using Marten;
using Marten.Schema;
using HourBooking.Contracts;

namespace HourBooking;

/// <summary>
/// The world the app wakes up in when you run it locally. Registered only in Development.
///
/// Two different kinds of thing are seeded here and it is worth keeping them apart:
///
///   * The membership and calendar facts are GENESIS EVENTS, which is what the model already says
///     they are — "we can use genesis events wherever we need starting data", the expert's own words.
///     They carry origin= rather than from=, so nothing in this system will ever produce them.
///
///   * BookingMonthStarted is a DEV SHORTCUT. It is really produced by the start-month automation,
///     a slice that is still in-design. Appending it directly stands in for that automation so the
///     Timesheet screen has an open month to book into. When start-month is built, this goes.
///
/// The test suite does NOT use this. It has its own SeedData with fixed ids, because a test needs a
/// world it controls and a demo needs a world that looks lived-in.
/// </summary>
public sealed class GenesisData : IInitialData
{
    public static readonly Guid EmployeeId = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000001");
    public static readonly Guid ApolloId = Guid.Parse("bbbbbbbb-0000-0000-0000-000000000001");
    public static readonly Guid GeminiId = Guid.Parse("bbbbbbbb-0000-0000-0000-000000000002");
    public static readonly Guid VoyagerId = Guid.Parse("bbbbbbbb-0000-0000-0000-000000000003");

    public const string EmployeeName = "Ada Lovelace";
    public const string Month = "2026-08";

    public async Task Populate(IDocumentStore store, CancellationToken cancellation)
    {
        // Idempotent: Populate runs on every startup, and appending the same genesis twice would
        // double every row in MyProjects.
        await using var query = store.QuerySession();
        if (await query.Query<Views.MyProjects>().AnyAsync(cancellation)) return;

        await using var session = store.LightweightSession();
        var at = new DateTimeOffset(2026, 8, 1, 8, 0, 0, TimeSpan.Zero);

        session.Events.Append($"membership:{EmployeeId}:{ApolloId}",
            new EmployeeAssignedToProject(EmployeeId, ApolloId, "Apollo", at));
        session.Events.Append($"membership:{EmployeeId}:{GeminiId}",
            new EmployeeAssignedToProject(EmployeeId, GeminiId, "Gemini", at));

        // Left the project, so booking against it must be refused — the UI can then show why.
        session.Events.Append($"membership:{EmployeeId}:{VoyagerId}",
            new EmployeeAssignedToProject(EmployeeId, VoyagerId, "Voyager", at),
            new EmployeeRemovedFromProject(EmployeeId, VoyagerId, new DateOnly(2026, 8, 1), at));

        // The dev shortcut standing in for the start-month automation.
        session.Events.Append($"monthClosure:{EmployeeId}:{Month}",
            new BookingMonthStarted(EmployeeId, EmployeeName, Month, at));

        // A day already booked, so the screen has something on it and the once-per-day+project rule
        // is visible without having to trigger it by hand.
        session.Events.Append($"timesheet:{EmployeeId}:{Month}",
            new HoursBooked(Guid.NewGuid(), EmployeeId, Month, ApolloId,
                new DateOnly(2026, 8, 3), 7.5m, "sprint planning", at));

        await session.SaveChangesAsync(cancellation);
    }
}
